/* ---------- sound ---------- */
let ac=null;
function tone(freqs,dur=0.12,type='sine',gap=0.09,vol=0.18){
  if(muted) return;
  try{
    ac = ac || new (window.AudioContext||window.webkitAudioContext)();
    freqs.forEach((f,i)=>{
      const o=ac.createOscillator(), g=ac.createGain(), t=ac.currentTime+i*gap;
      o.type=type; o.frequency.value=f; g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(vol,t+0.02);
      g.gain.exponentialRampToValueAtTime(0.001,t+dur); o.connect(g); g.connect(ac.destination); o.start(t); o.stop(t+dur+0.02);
    });
  }catch(e){}
}
const sOk=()=>tone([660,880,1100],0.18,'triangle');
const sNo=()=>tone([300,220],0.2,'square',0.12,0.08);
const sWin=()=>tone([523,659,784,1046,1318],0.25,'triangle',0.12);
const sBuzz=()=>tone([180,190,180,190],0.07,'sawtooth',0.06,0.04);

/* ---------- icons for the two choices ---------- */
const MK_A=`<svg class="mk" viewBox="-20 -20 40 40" aria-hidden="true"><circle r="18" fill="#f5a623" stroke="#8a5a00" stroke-width="3"/><path d="M0,-10 L3,-3 L10,-3 L4,2 L6,10 L0,5 L-6,10 L-4,2 L-10,-3 L-3,-3Z" fill="#fff"/></svg>`;
const MK_B=`<svg class="mk" viewBox="-20 -20 40 40" aria-hidden="true"><circle r="18" fill="#e64980" stroke="#8c1d48" stroke-width="3"/><path d="M0,9 C-14,0 -10,-11 -4,-11 C-1,-11 0,-8 0,-7 C0,-8 1,-11 4,-11 C10,-11 14,0 0,9Z" fill="#fff"/></svg>`;
const flagSvg=(x,y,kind)=>`<g class="flag" transform="translate(${x},${y}) scale(1.05)">${kind==='A'
  ? '<circle r="18" fill="#f5a623" stroke="#8a5a00" stroke-width="3"/><path d="M0,-10 L3,-3 L10,-3 L4,2 L6,10 L0,5 L-6,10 L-4,2 L-10,-3 L-3,-3Z" fill="#fff"/>'
  : '<circle r="18" fill="#e64980" stroke="#8c1d48" stroke-width="3"/><path d="M0,9 C-14,0 -10,-11 -4,-11 C-1,-11 0,-8 0,-7 C0,-8 1,-11 4,-11 C10,-11 14,0 0,9Z" fill="#fff"/>'}</g>`;

/* ---------- home ---------- */
const PICS={
  flower:`<svg viewBox="-60 -60 120 120" width="90" height="90"><path d="M0,10 Q-4,40 0,58" stroke="#3f9b4a" stroke-width="7" fill="none"/>${[0,60,120,180,240,300].map(a=>`<circle cx="0" cy="-22" r="16" fill="#ff6fa5" stroke="#a83f6c" stroke-width="2.5" transform="rotate(${a})"/>`).join('')}<circle r="14" fill="#ffd23f" stroke="#c98a00" stroke-width="2.5"/></svg>`,
  tree:`<svg viewBox="-60 -70 120 130" width="90" height="90"><rect x="-10" y="5" width="20" height="50" rx="5" fill="#8a5a2b"/><circle cx="0" cy="-25" r="42" fill="#49b04f"/><circle cx="-34" cy="0" r="26" fill="#3fa046"/><circle cx="34" cy="0" r="26" fill="#3fa046"/>${[[-20,-35],[15,-40],[0,-10],[-35,5],[30,0],[20,-20]].map(([a,b])=>`<circle cx="${a}" cy="${b}" r="8" fill="#ff7b2e" stroke="#a34700" stroke-width="2"/>`).join('')}</svg>`,
  sea:`<svg viewBox="-100 -100 250 180" width="94" height="80"><path d="M-90,10 Q-80,-60 10,-55 Q90,-50 95,10 Q90,45 0,48 Q-70,48 -90,10 Z" fill="#4c8ed9" stroke="#24508a" stroke-width="5"/><path d="M90,0 L135,-30 L125,10 L140,40 Z" fill="#4c8ed9" stroke="#24508a" stroke-width="5"/><circle cx="-50" cy="-10" r="7" fill="#123"/><path d="M-75,15 Q-62,25 -48,16" stroke="#123" stroke-width="4" fill="none"/><path d="M-20,-55 Q-30,-85 -45,-90 M-20,-55 Q-15,-88 0,-95 M-20,-55 Q-5,-80 15,-80" stroke="#7cc8ff" stroke-width="6" fill="none" stroke-linecap="round"/></svg>`
};
function renderHome(){
  const box=document.getElementById('stories'); box.innerHTML='';
  DATA.stories.forEach((s,si)=>{
    const th=THEME[s.id];
    const el=document.createElement('div'); el.className='story'; el.style.setProperty('--c',th.c); el.style.setProperty('--bg',th.bg);
    el.innerHTML=`<div class="pic">${PICS[s.id]}</div><div><h2>${s.title}</h2><p class="range">${th.range}</p><div class="stages"></div></div>`;
    const sg=el.querySelector('.stages');
    s.stages.forEach((g,gi)=>{
      const k=`${s.id}-${gi}`, n=stars[k]||0;
      const b=document.createElement('button'); b.className='stg';
      b.innerHTML=`المرحلة ${ORD[gi]}<span class="st">${n?'★'.repeat(n):''}</span>`;
      b.setAttribute('aria-label',`${s.title}، المرحلة ${ORD[gi]}${n?`، ${AR(n)} نجوم`:''}`);
      b.onclick=()=>startStage(si,gi);
      sg.appendChild(b);
    });
    box.appendChild(el);
  });
}

/* ---------- play ---------- */
let G=null; // game state
const $=id=>document.getElementById(id);
function pathFor(row,i,side,correct,rows){
  const x= side==='L'?XL:XR;
  if(correct){ const ny= i<rows.length-1 ? rows[i+1].y : ENDY; return [[CX,row.y],[x,row.y],[x,row.mid],[CX,row.mid],[CX,ny]]; }
  const stop = side==='L' ? CX-(2*R+20)-44 : CX+(2*R+20)+44;
  return [[CX,row.y],[x,row.y],[x,row.mid],[stop,row.mid]];
}
function startStage(si,gi){
  const s=DATA.stories[si], g=s.stages[gi], th=THEME[s.id];
  G={si,gi,s,g,th,i:-1,mist:0,busy:true,bx:CX,by:START_Y,face:1};
  document.documentElement.style.setProperty('--c',th.c);
  $('play').style.setProperty('--c',th.c);
  $('pt').textContent=s.title;
  $('ps').textContent=`المرحلة ${ORD[gi]} من ${AR(s.stages.length)}`;
  updateOops();
  const map=$('map');
  map.innerHTML=SVGS[`${s.id}-${gi}`];
  const svg=map.querySelector('svg');
  svg.setAttribute('role','img'); svg.setAttribute('aria-label','خريطة المتاهة');
  const ns='http://www.w3.org/2000/svg';
  const layer=document.createElementNS(ns,'g'); layer.id='trail'; svg.appendChild(layer);
  const flags=document.createElementNS(ns,'g'); flags.id='flags'; svg.appendChild(flags);
  const startMark=document.createElementNS(ns,'g');
  startMark.innerHTML=`<circle cx="${CX}" cy="${START_Y}" r="26" fill="#fff" stroke="${th.c}" stroke-width="5"/><text x="${CX}" y="${START_Y+8}" text-anchor="middle" font-family="Tajawal" font-weight="800" font-size="22" fill="${th.c}">ابدأ</text>`;
  svg.appendChild(startMark);
  const beeG=document.createElementNS(ns,'g'); beeG.id='bee'; beeG.innerHTML=`<g id="beeInner">${BEE}</g>`; svg.appendChild(beeG);
  placeBee(CX-70,START_Y,1);
  showScreen('play');
  map.scrollTop=0;
  // show start verse
  $('ask').style.display='none'; $('say').style.display='block';
  $('sayOk').textContent='نبدأ من هنا، اقرأ الآية:';
  $('sayV').textContent=T[g.start];
  $('goBtn').style.display='block'; $('goBtn').textContent='يلا نبدأ';
  $('goBtn').onclick=()=>{ $('goBtn').style.display='none'; flyTo([[CX-70,START_Y],[CX,START_Y],[CX,g.rows[0].y]]).then(()=>nextFork()); };
  setTimeout(()=>$('goBtn').focus(),50);
}
function placeBee(x,y,face){
  G.bx=x; G.by=y; if(face) G.face=face;
  const b=$('bee'); if(!b) return;
  b.setAttribute('transform',`translate(${x},${y}) scale(${0.6*G.face},0.6)`);
}
function follow(){
  const map=$('map'), svg=map.querySelector('svg'); if(!svg) return;
  const scale=svg.getBoundingClientRect().width/1000;
  const target=(G.by-200)*scale - map.clientHeight*0.42;
  map.scrollTop=Math.max(0,target);
}
function flyTo(pts,drawTrail){
  return new Promise(res=>{
    let seg=0, t0=null, from=pts[0];
    const segs=[]; for(let i=0;i<pts.length-1;i++){const a=pts[i],b=pts[i+1];segs.push({a,b,len:Math.hypot(b[0]-a[0],b[1]-a[1])});}
    const total=segs.reduce((s,x)=>s+x.len,0);
    let trail=null;
    if(drawTrail){
      const ns='http://www.w3.org/2000/svg';
      trail=document.createElementNS(ns,'polyline');
      trail.setAttribute('fill','none'); trail.setAttribute('stroke',drawTrail); trail.setAttribute('stroke-width','8');
      trail.setAttribute('stroke-linecap','round'); trail.setAttribute('stroke-linejoin','round'); trail.setAttribute('stroke-dasharray','2 14');
      $('trail').appendChild(trail);
    }
    const done=[from];
    function step(ts){
      if(!t0) t0=ts;
      let d=(ts-t0)/1000*SPEED, acc=0, x=pts[pts.length-1][0], y=pts[pts.length-1][1], finished=true, idx=segs.length;
      for(let i=0;i<segs.length;i++){
        const s=segs[i];
        if(d<=acc+s.len){ const f=(d-acc)/s.len; x=s.a[0]+(s.b[0]-s.a[0])*f; y=s.a[1]+(s.b[1]-s.a[1])*f; finished=false; idx=i; break; }
        acc+=s.len;
      }
      const cur=segs[Math.min(idx,segs.length-1)];
      const dx=cur.b[0]-cur.a[0]; const face= dx>1?1:(dx<-1?-1:G.face);
      placeBee(x,y,face);
      if(trail){ const p=pts.slice(0,idx+1).concat([[x,y]]); trail.setAttribute('points',p.map(q=>q.join(',')).join(' ')); }
      follow();
      if(finished || total===0){ res(); } else requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  });
}
function updateOops(){ $('oops').innerHTML = G.mist ? `✗ ${AR(G.mist)}` : ''; $('oops').setAttribute('aria-label',`عدد الغلطات ${G.mist}`); }
function nextFork(){
  G.i++;
  const rows=G.g.rows;
  if(G.i>=rows.length){ return finish(); }
  const r=rows[G.i];
  // flags on the map: L branch & R branch
  const fl=$('flags'); fl.innerHTML='';
  // the choice on the right side of the screen = R branch
  const kinds={R:'B',L:'A'};
  const textFor = side => side===r.side ? T[r.k] : T[r.d];
  const cA=$('cA'), cB=$('cB');           // A = left branch, B = right branch
  cA.innerHTML=MK_A+`<span>${textFor('L')}</span>`; cB.innerHTML=MK_B+`<span>${textFor('R')}</span>`;
  [cA,cB].forEach(c=>{c.classList.remove('no');c.disabled=false;});
  cA.onclick=()=>choose('L',cA); cB.onclick=()=>choose('R',cB);
  $('say').style.display='none'; $('ask').style.display='block';
  $('prompt').textContent='إيه الآية اللي بعدها؟ اختار الطريق';
  G.busy=false;
}
async function choose(side,btn){
  if(G.busy||btn.disabled) return; G.busy=true;
  const r=G.g.rows[G.i], ok= side===r.side;
  $('cA').disabled=true; $('cB').disabled=true;
  if(ok){
    sOk();
    $('ask').style.display='none'; $('say').style.display='block';
    $('sayOk').textContent='صح! ردّدها معانا'; $('sayV').textContent=T[r.k]; $('goBtn').style.display='none';
    $('flags').innerHTML='';
    await flyTo(pathFor(r,G.i,side,true,G.g.rows),'#2f9e44');
    await wait(reduce?150:500);
    nextFork();
  }else{
    G.mist++; updateOops();
    $('prompt').textContent='خلينا نشوف الطريق ده…';
    const p=pathFor(r,G.i,side,false,G.g.rows);
    await flyTo(p,'rgba(224,49,49,.55)');
    sBuzz(); const map=$('map'); map.classList.add('shake'); setTimeout(()=>map.classList.remove('shake'),450);
    $('prompt').textContent='الطريق ده مقفول! ارجع وجرّب التاني';
    await wait(reduce?200:650);
    sNo();
    await flyTo(p.slice().reverse());
    btn.classList.add('no');
    const other= side==='L'?$('cB'):$('cA'); other.disabled=false;
    $('prompt').textContent='جرّب الطريق التاني';
    G.busy=false; other.focus();
  }
}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
function finish(){
  sWin();
  const n = G.mist===0?3 : G.mist<=2?2 : 1;
  const key=`${G.s.id}-${G.gi}`; if((stars[key]||0)<n){stars[key]=n;saveStars();}
  const last = G.gi===G.s.stages.length-1;
  $('wt').textContent = last ? G.th.end : G.th.mid;
  $('wstars').innerHTML = [1,2,3].map(i=>`<span class="${i<=n?'':'off'}">★</span>`).join('');
  $('wp').textContent = G.mist===0 ? 'ولا غلطة! ما شاء الله عليك' : (G.mist===1?'خلّصت المرحلة بغلطة واحدة':G.mist===2?'خلّصت المرحلة بغلطتين':`خلّصت المرحلة بـ ${AR(G.mist)} غلطات`);
  const hasNext = !last || G.si<DATA.stories.length-1;
  $('wnext').style.display = hasNext?'block':'none';
  $('wnext').textContent = last ? 'القصة اللي بعدها' : 'المرحلة اللي بعدها';
  $('wnext').onclick=()=>{ hideWin(); if(!last) startStage(G.si,G.gi+1); else startStage(G.si+1,0); };
  $('wagain').onclick=()=>{ hideWin(); startStage(G.si,G.gi); };
  $('whome').onclick=()=>{ hideWin(); goHome(); };
  document.querySelector('.win').style.setProperty('--c',G.th.c);
  $('veil').classList.add('on'); setTimeout(()=>($('wnext').style.display!=='none'?$('wnext'):$('whome')).focus(),50);
}
function hideWin(){ $('veil').classList.remove('on'); }
function showScreen(id){ document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('on',s.id===id)); }
function goHome(){ renderHome(); showScreen('home'); }
$('back').onclick=goHome;
function setSnd(){ $('snd').textContent = muted?'🔇':'🔊'; $('snd').setAttribute('aria-label',muted?'شغّل الصوت':'اقفل الصوت'); }
$('snd').onclick=()=>{ muted=!muted; try{localStorage.setItem('nona-muted',muted?'1':'0');}catch(e){} setSnd(); };
setSnd(); renderHome();
